void GetExtensionViews(const v8::FunctionCallbackInfo<v8::Value>& args) {
    v8::Isolate* isolate = args.GetIsolate();
    v8::Local<v8::Context> context = isolate->GetCurrentContext();

    if (args.Length() < 2) {
        isolate->ThrowException(v8::Exception::Error(
            v8::String::NewFromUtf8(isolate, "Missing required arguments.").ToLocalChecked()));
        return;
    }

    if (!args[0]->IsNumber() || !args[1]->IsString()) {
        isolate->ThrowException(v8::Exception::TypeError(
            v8::String::NewFromUtf8(isolate, "Invalid argument types.").ToLocalChecked()));
        return;
    }

    int window_id = args[0].As<v8::Number>()->Value();
    v8::String::Value view_type_str(isolate, args[1]);
    std::string view_type(*view_type_str);

    std::string extension_id = GetExtensionId(window_id);
    if (extension_id.empty()) {
        isolate->ThrowException(v8::Exception::Error(
            v8::String::NewFromUtf8(isolate, "No extension found for the given window.").ToLocalChecked()));
        return;
    }

    std::vector<ViewInfo> frames = GetRelevantFrames(extension_id);
    std::vector<ViewInfo> main_views;

    for (const auto& frame : frames) {
        if (!frame.is_iframe) {
            main_views.push_back(frame);
        }
    }

    v8::Local<v8::Array> result = v8::Array::New(isolate, main_views.size());
    for (size_t i = 0; i < main_views.size(); ++i) {
        v8::Local<v8::Object> view_obj = v8::Object::New(isolate);
        view_obj->Set(context, v8::String::NewFromUtf8(isolate, "id").ToLocalChecked(), v8::Integer::New(isolate, main_views[i].id));
        view_obj->Set(context, v8::String::NewFromUtf8(isolate, "type").ToLocalChecked(), v8::String::NewFromUtf8(isolate, main_views[i].type.c_str()).ToLocalChecked());
        result->Set(context, i, view_obj).Check();
    }

    args.GetReturnValue().Set(result);
}
